#!/usr/bin/env python3
"""Flat SVG illustrations for public/img/tv-music used by Advanced 1 / 7C TV & music (original artwork).
Run once: python3 scripts/draw-tv-music-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'tv-music'
OUT.mkdir(parents=True, exist_ok=True)
BG = lambda c='#ede7f6': f'<rect width="64" height="64" rx="8" fill="{c}"/>'
TV = lambda inner, frame='#333': f'<rect x="6" y="8" width="52" height="38" rx="4" fill="{frame}"/><rect x="10" y="12" width="44" height="30" fill="#1e2a44"/>{inner}<rect x="26" y="46" width="12" height="4" fill="#555"/><rect x="18" y="50" width="28" height="3" rx="1" fill="#555"/>'
PERSON = lambda x, y, shirt='#e63946', r=3.5: f'<circle cx="{x}" cy="{y}" r="{r}" fill="#f5c6a5"/><rect x="{x - r}" y="{y + r}" width="{2*r}" height="{r*2.6}" rx="2" fill="{shirt}"/>'
NOTE = lambda x, y, c='#333', s=1: f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="0" cy="8" rx="4" ry="3" fill="{c}"/><rect x="3" y="-6" width="2" height="14" fill="{c}"/><path d="M5 -6 q6 2 6 8 q0 -4 -6 -4z" fill="{c}"/></g>'
MIC = lambda x, y: f'<rect x="{x-3}" y="{y}" width="6" height="10" rx="3" fill="#333"/><rect x="{x-1}" y="{y+10}" width="2" height="8" fill="#333"/><rect x="{x-5}" y="{y+18}" width="10" height="2" fill="#333"/>'
T = lambda x, y, txt, size=6, c='#fff': f'<text x="{x}" y="{y}" font-family="sans-serif" font-size="{size}" font-weight="bold" fill="{c}" text-anchor="middle">{txt}</text>'

ICONS = {
    'game-show': BG() + TV('<rect x="14" y="16" width="36" height="8" rx="2" fill="#ffd54a"/>' + T(32, 22, '$1,000,000', 5, '#333') + PERSON(24, 32, '#4d96ff', 3) + PERSON(40, 32, '#e63946', 3) + '<rect x="30" y="34" width="4" height="6" fill="#ffd54a"/>'),
    'talk-show': BG() + TV('<rect x="12" y="30" width="40" height="10" fill="#8d5524"/>' + PERSON(20, 24, '#333', 3) + PERSON(36, 24, '#e63946', 3) + PERSON(46, 24, '#4d96ff', 3) + '<rect x="40" y="28" width="12" height="2" fill="#fff"/>' + T(26, 17, 'LATE SHOW', 4.5, '#ffd54a')),
    'drama': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#2a1a2e"/>' + PERSON(24, 26, '#607d8b', 3.5) + PERSON(40, 26, '#9c27b0', 3.5) + '<path d="M18 16 L22 20 M46 16 L42 20" stroke="#bde0fe" stroke-width="1"/><ellipse cx="32" cy="38" rx="14" ry="3" fill="#000" opacity=".4"/>'),
    'reality-show': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#fde2c8"/>' + PERSON(18, 26, '#e63946', 3) + PERSON(28, 24, '#4d96ff', 3) + PERSON(38, 26, '#ffd54a', 3) + PERSON(48, 24, '#2e7d32', 3) + '<rect x="12" y="14" width="10" height="4" rx="1" fill="#e63946"/>' + T(17, 17.2, 'LIVE', 3, '#fff') + '<rect x="40" y="14" width="12" height="4" rx="1" fill="#333"/>' + T(46, 17.2, 'CAM 2', 3)),
    'cartoon': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#8ecae6"/><circle cx="32" cy="24" r="7" fill="#ffd54a"/><path d="M26 19 l2 -5 l2 4 l2 -4 l2 4 l2 -5 l2 5" fill="#ffd54a"/><circle cx="29" cy="23" r="1.5" fill="#fff"/><circle cx="35" cy="23" r="1.5" fill="#fff"/><circle cx="29.5" cy="23" r=".7" fill="#000"/><circle cx="35.5" cy="23" r=".7" fill="#000"/><path d="M29 28 q3 2 6 0" stroke="#000" stroke-width="1" fill="none"/><rect x="26" y="31" width="12" height="9" fill="#e63946"/>'),
    'sitcom': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#fff3e0"/><rect x="14" y="30" width="36" height="8" rx="3" fill="#e63946"/>' + PERSON(22, 24, '#4d96ff', 3) + PERSON(32, 23, '#ffd54a', 3) + PERSON(42, 24, '#2e7d32', 3) + T(32, 18, 'HA HA HA', 4.5, '#333')),
    'soap-opera': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#f8bbd0"/>' + PERSON(24, 26, '#9c27b0', 3.5) + PERSON(40, 26, '#333', 3.5) + '<path d="M32 16 c-2 -3 -6 0 -3 3 l3 3 l3 -3 c3 -3 -1 -6 -3 -3z" fill="#e63946"/><path d="M26 32 Q24 36 25 38" stroke="#4d96ff" stroke-width="1.5" fill="none"/>'),
    'the-news': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#0d3b66"/>' + PERSON(24, 24, '#333', 4) + '<rect x="36" y="16" width="14" height="10" fill="#4d96ff"/><rect x="10" y="34" width="44" height="6" fill="#e63946"/>' + T(32, 38.5, 'BREAKING NEWS', 4) + '<rect x="10" y="40" width="44" height="2" fill="#ffd54a"/>'),
    'talent-show': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#1a237e"/><path d="M14 12 L24 42 M50 12 L40 42" stroke="#ffd54a" stroke-width="3" opacity=".6"/>' + PERSON(32, 24, '#e63946', 3.5) + MIC(38, 25).replace('width="6" height="10"', 'width="4" height="6"') + ''.join(f'<text x="{x}" y="18" font-family="sans-serif" font-size="6" fill="#ffd54a">★</text>' for x in (14, 44))),
    'ads': BG('#fff8e1') + TV('<rect x="10" y="12" width="44" height="30" fill="#ffd54a"/>' + T(32, 24, 'SALE!', 9, '#e63946') + T(32, 34, '50% OFF · BUY NOW', 4, '#333')),
    'audience': BG('#1e2a44') + ''.join(f'<circle cx="{x}" cy="{y}" r="3.5" fill="{c}"/><rect x="{x-4}" y="{y+3}" width="8" height="8" rx="2" fill="{s}"/>' for x, y, c, s in [(8, 40, '#f5c6a5', '#e63946'), (20, 42, '#8d5524', '#4d96ff'), (32, 40, '#f5c6a5', '#ffd54a'), (44, 42, '#f5c6a5', '#2e7d32'), (56, 40, '#8d5524', '#e63946'), (14, 26, '#f5c6a5', '#9c27b0'), (26, 28, '#f5c6a5', '#e63946'), (38, 26, '#8d5524', '#4d96ff'), (50, 28, '#f5c6a5', '#ffd54a')]) + '<path d="M10 18 L8 10 M56 18 L58 10" stroke="#f5c6a5" stroke-width="2.5" stroke-linecap="round"/><rect x="0" y="54" width="64" height="10" fill="#333"/>',
    'channel': BG() + TV(T(32, 30, '7', 18, '#ffd54a') + '<rect x="14" y="36" width="36" height="3" fill="#4d96ff"/>') + '<rect x="46" y="48" width="14" height="8" rx="2" fill="#555"/><circle cx="50" cy="52" r="1.5" fill="#e63946"/><circle cx="56" cy="52" r="1.5" fill="#2e7d32"/>',
    'episode': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#2a1a2e"/>' + T(32, 24, 'EPISODE', 6, '#ffd54a') + T(32, 36, 'S2 · E5', 7)),
    'host': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#0d3b66"/><circle cx="32" cy="22" r="5" fill="#f5c6a5"/><rect x="25" y="27" width="14" height="14" rx="3" fill="#333"/><rect x="31" y="27" width="2" height="8" fill="#fff"/><rect x="26" y="31" width="12" height="3" fill="#e63946"/><path d="M39 30 L46 24" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/>' + MIC(47, 16).replace('width="6" height="10"', 'width="4" height="7"')),
    'series': BG() + '<rect x="6" y="14" width="14" height="36" rx="2" fill="#4d96ff"/><rect x="22" y="14" width="14" height="36" rx="2" fill="#e63946"/><rect x="38" y="14" width="14" height="36" rx="2" fill="#2e7d32"/>' + T(13, 36, '1', 10) + T(29, 36, '2', 10) + T(45, 36, '3', 10) + '<rect x="54" y="14" width="6" height="36" rx="2" fill="#ffd54a"/>',
    'season': BG() + TV('<rect x="10" y="12" width="44" height="30" fill="#1e2a44"/>' + T(32, 24, 'SEASON 3', 7, '#ffd54a') + ''.join(f'<rect x="{12 + i*4.2}" y="30" width="3.5" height="8" fill="{"#4d96ff" if i<7 else "#555"}"/>' for i in range(10))),
    'band': BG('#1a237e') + '<rect x="0" y="48" width="64" height="16" fill="#333"/>' + PERSON(14, 22, '#e63946', 4) + PERSON(32, 18, '#ffd54a', 4) + PERSON(50, 22, '#4d96ff', 4) + '<path d="M6 30 L18 36" stroke="#8d5524" stroke-width="3"/><path d="M46 36 L58 30" stroke="#8d5524" stroke-width="3"/>' + MIC(32, 26).replace('width="6" height="10"', 'width="4" height="6"') + '<circle cx="40" cy="42" r="5" fill="#ccc" stroke="#333"/>',
    'tracks': BG() + '<circle cx="18" cy="32" r="14" fill="#222"/><circle cx="18" cy="32" r="5" fill="#e63946"/><circle cx="18" cy="32" r="1.5" fill="#fff"/>' + ''.join(f'<rect x="36" y="{14 + i*8}" width="{22 - i*2}" height="3" rx="1" fill="#555"/>' + f'<text x="38" y="{13 + i*8}" font-family="sans-serif" font-size="3" fill="#333">{i+1}. Track</text>' for i in range(5)),
    'playlist': BG() + '<rect x="12" y="8" width="40" height="48" rx="4" fill="#fff" stroke="#333"/>' + ''.join(f'<path d="M18 {16 + i*9} l4 3 l-4 3z" fill="#2e7d32"/><rect x="26" y="{17 + i*9}" width="20" height="2.5" rx="1" fill="#555"/>' for i in range(5)) + NOTE(44, 20, '#e63946', .8),
    'on-tour': BG('#cfe8ff') + '<rect x="0" y="40" width="64" height="24" fill="#4a4e57"/><rect x="0" y="50" width="64" height="2" fill="#ffd54a"/><rect x="8" y="22" width="44" height="20" rx="3" fill="#9c27b0"/><rect x="12" y="25" width="36" height="7" fill="#bde0fe"/><circle cx="16" cy="44" r="4" fill="#222"/><circle cx="44" cy="44" r="4" fill="#222"/>' + T(30, 39, 'WORLD TOUR', 4.5) + NOTE(54, 12, '#333', .8) + NOTE(10, 14, '#333', .7),
    'hits': BG('#fff8e1') + '<rect x="10" y="40" width="10" height="14" fill="#4d96ff"/><rect x="22" y="30" width="10" height="24" fill="#2e7d32"/><rect x="34" y="18" width="10" height="36" fill="#e63946"/><rect x="46" y="26" width="10" height="28" fill="#ffd54a"/>' + T(39, 14, '#1', 7, '#e63946') + T(15, 59, '4', 4, '#333') + T(27, 59, '3', 4, '#333') + T(39, 59, '1', 4, '#333') + T(51, 59, '2', 4, '#333'),
    'live': BG('#1a237e') + '<rect x="0" y="48" width="64" height="16" fill="#333"/><path d="M10 10 L28 48 M54 10 L36 48" stroke="#ffd54a" stroke-width="4" opacity=".5"/>' + PERSON(32, 22, '#e63946', 4) + MIC(32, 30).replace('width="6" height="10"', 'width="4" height="6"') + '<rect x="4" y="6" width="16" height="7" rx="1" fill="#e63946"/>' + T(12, 11.5, 'LIVE', 5) + ''.join(f'<circle cx="{x}" cy="54" r="2.5" fill="#f5c6a5"/>' for x in (12, 20, 44, 52)),
    'album': BG() + '<rect x="12" y="12" width="40" height="40" rx="2" fill="#e63946"/><rect x="16" y="16" width="32" height="32" fill="#1e2a44"/><circle cx="32" cy="32" r="10" fill="#ffd54a"/>' + NOTE(30, 26, '#1e2a44', .9) + '<rect x="12" y="52" width="40" height="3" fill="#8d5524"/>' + T(32, 60, 'NEW ALBUM', 4, '#333'),
    'could-ride': BG('#cfe8ff') + '<rect x="0" y="48" width="64" height="16" fill="#43a047"/><circle cx="16" cy="46" r="7" fill="none" stroke="#333" stroke-width="2.5"/><circle cx="44" cy="46" r="7" fill="none" stroke="#333" stroke-width="2.5"/><path d="M16 46 L26 32 L40 32 L44 46 M26 32 L22 46 M30 46 L28 32" stroke="#e63946" stroke-width="2.5" fill="none"/>' + PERSON(32, 18, '#4d96ff', 3.5) + '<path d="M32 28 L26 34 M34 30 L32 40" stroke="#222" stroke-width="2.5" stroke-linecap="round"/>' + T(52, 14, '✓', 10, '#2e7d32'),
    'able-to': BG('#e8f5e9') + '<circle cx="32" cy="30" r="18" fill="#2e7d32"/><path d="M22 30 L29 37 L43 23" stroke="#fff" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" fill="none"/>' + T(32, 58, 'ABLE TO', 7, '#333'),
    'not-able': BG('#fce4ec') + '<circle cx="32" cy="30" r="18" fill="#e63946"/><path d="M24 22 L40 38 M40 22 L24 38" stroke="#fff" stroke-width="5" stroke-linecap="round"/>' + T(32, 58, "COULDN'T", 7, '#333'),
}

for name, body in ICONS.items():
    (OUT / f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">{body}</svg>\n')
print(f'{len(ICONS)} icons written to {OUT}')
